\begin{theorem}
\label{23septt3aa}Let $E\subseteq W\subseteq X$ where the injection map is
continuous from $W$ to $X$ and compact from $E$ to $W$. Let $p\geq 1$, let $
q>1$, and define
\begin{equation*}
S\equiv \{u\in L^{p}\left( \left[ a,b\right] ;E\right) :\text{for some }C,
\text{ }\left\Vert u\left( t\right) -u\left( s\right) \right\Vert _{X}\leq
C\left\vert t-s\right\vert ^{1/q}\text{ }
\end{equation*}
\begin{equation*}
\text{and }\left\vert \left\vert u\right\vert \right\vert _{L^{p}\left(
\left[ a,b\right] ;E\right) }\leq R\}.
\end{equation*}
Thus $S$ is bounded in $L^{p}\left( a,b;E\right) $ and Holder continuous
into $X$. Then $S$ is precompact in $L^{p}\left( \left[ a,b\right] ;W\right)
$.
